for r in records:
 text=Path(r['raw']).read_text();v=dict(r)
 for event,label in [('instructions','instructions'),('cycles','cycles')]:
  m=re.search(r'^\s*([0-9.,]+)\s+cpu_core/'+event+r'/u',text,re.M);assert m,(r['raw'],event);v[label]=float(m[1].replace(',',''))/r['conversions']
 parsed.append(v)
cells=[];lines=['Actual fifth retained Bench.measure trial, perf main TID only. Counts per conversion, wall ns.','Arms: '+' / '.join(arms),'Normal JIT; exact Work/timer byte identity; diagnostic controls only.']
for row,name in enumerate(b['rows']):
 for direction in ['Lower','Upper']:
  cell={'row':row,'name':name,'direction':direction,'arms':{}}
  for arm in arms:
   values=[r for r in parsed if(r['row'],r['direction'],r['arm'])==(row,direction,arm)]
   if not values:continue
   cell['arms'][arm]={'launches':len(values),'instructions':{'median':statistics.median(r['instructions']for r in values),'min':min(r['instructions']for r in values),'max':max(r['instructions']for r in values)},'cycles':{'median':statistics.median(r['cycles']for r in values),'min':min(r['cycles']for r in values),'max':max(r['cycles']for r in values)},'wallNs':{'median':statistics.median(r['trialNsPerConversion']for r in values),'min':min(r['trialNsPerConversion']for r in values),'max':max(r['trialNsPerConversion']for r in values)}}
  cells.append(cell);lines.append(name+' '+direction+' | '+' / '.join(('%s %.2f [%.2f,%.2f] ns %.2f'%(arm,x['instructions']['median'],x['instructions']['min'],x['instructions']['max'],x['wallNs']['median']))for arm,x in cell['arms'].items()))
